SELECT value FROM (SELECT FORMAT_DATE('%Y-%m', DATE_TRUNC(CURRENT_DATE(), MONTH)) AS period, ROUND(SAFE_DIVIDE( SUM(CASE WHEN TxnDate >= DATE_TRUNC(CURRENT_DATE(), MONTH) AND TxnDate < CURRENT_DATE() THEN SaaSAmount + SaaSExpense ELSE 0 END), SUM(CASE WHEN TxnDate >= DATE_TRUNC(DATE_SUB(CURRENT_DATE(), INTERVAL 1 MONTH), MONTH) AND TxnDate < DATE_SUB(CURRENT_DATE(), INTERVAL 1 MONTH) THEN SaaSAmount + SaaSExpense ELSE 0 END) ) * SUM(CASE WHEN TxnDate >= DATE_TRUNC(DATE_SUB(CURRENT_DATE(), INTERVAL 1 MONTH), MONTH) AND TxnDate < DATE_TRUNC(CURRENT_DATE(), MONTH) THEN SaaSAmount + SaaSExpense ELSE 0 END), 2) AS value FROM `project-for-method-dw.revenue.v_total_net_saas`) WHERE CAST(period AS STRING) LIKE '2026-07%'